     1→/**
     2→ * Image Generation API Route
     3→ * POST /api/generate-image
     4→ *
     5→ * Handles outfit image generation requests using OpenRouter's Gemini 2.5 Flash Preview model
     6→ *
     7→ * Features:
     8→ * - Server-side rate limiting (10 requests per minute per IP)
     9→ * - Request validation
    10→ * - Error handling with appropriate HTTP status codes
    11→ * - Logging for debugging
    12→ */
    13→
    14→import { NextRequest, NextResponse } from 'next/server';
    15→import { OpenRouterImageClient } from '@/lib/services/image-generation-service';
    16→import type { ImageGenerationRequest } from '@/lib/types/image-types';
    17→
    18→/**
    19→ * Rate limiting configuration
    20→ * Tracks request counts per IP address
    21→ */
    22→const rateLimitMap = new Map<string, { count: number; resetTime: number }>();
    23→const RATE_LIMIT_WINDOW = 60000; // 1 minute in milliseconds
    24→const RATE_LIMIT_MAX_REQUESTS = 10;
    25→
    26→/**
    27→ * Checks if request is rate limited
    28→ *
    29→ * @param ip - Client IP address
    30→ * @returns true if rate limited, false if allowed
    31→ */
    32→function isRateLimited(ip: string): boolean {
    33→  const now = Date.now();
    34→  const record = rateLimitMap.get(ip);
    35→
    36→  // No record or window expired - create new record
    37→  if (!record || now > record.resetTime) {
    38→    rateLimitMap.set(ip, {
    39→      count: 1,
    40→      resetTime: now + RATE_LIMIT_WINDOW,
    41→    });
    42→    return false;
    43→  }
    44→
    45→  // Increment count
    46→  record.count++;
    47→
    48→  // Check if over limit
    49→  if (record.count > RATE_LIMIT_MAX_REQUESTS) {
    50→    return true;
    51→  }
    52→
    53→  return false;
    54→}
    55→
    56→/**
    57→ * Gets client IP address from request
    58→ *
    59→ * @param request - Next.js request object
    60→ * @returns IP address string
    61→ */
    62→function getClientIP(request: NextRequest): string {
    63→  // Try various headers that might contain the real IP
    64→  const forwarded = request.headers.get('x-forwarded-for');
    65→  if (forwarded) {
    66→    return forwarded.split(',')[0].trim();
    67→  }
    68→
    69→  const realIP = request.headers.get('x-real-ip');
    70→  if (realIP) {
    71→    return realIP;
    72→  }
    73→
    74→  // Fallback to a default value
    75→  return 'unknown';
    76→}
    77→
    78→/**
    79→ * POST handler for image generation
    80→ *
    81→ * Request body:
    82→ * {
    83→ *   description: string,
    84→ *   style?: {
    85→ *     photographyStyle?: string,
    86→ *     composition?: string,
    87→ *     lighting?: string,
    88→ *     aestheticContext?: string
    89→ *   }
    90→ * }
    91→ *
    92→ * Response:
    93→ * {
    94→ *   success: boolean,
    95→ *   imageUrl?: string,
    96→ *   imageBase64?: string,
    97→ *   error?: string,
    98→ *   message?: string
    99→ * }
   100→ */
   101→export async function POST(request: NextRequest) {
   102→  const startTime = Date.now();
   103→
   104→  try {
   105→    // Get client IP for rate limiting
   106→    const clientIP = getClientIP(request);
   107→
   108→    console.log('[API] Image generation request received from IP:', clientIP);
   109→
   110→    // Check rate limiting
   111→    if (isRateLimited(clientIP)) {
   112→      console.warn('[API] Rate limit exceeded for IP:', clientIP);
   113→      return NextResponse.json(
   114→        {
   115→          success: false,
   116→          error: 'RATE_LIMITED',
   117→          message: 'Too many requests. Please wait a minute before trying again.',
   118→        },
   119→        {
   120→          status: 429,
   121→          headers: {
   122→            'Retry-After': '60',
   123→          },
   124→        }
   125→      );
   126→    }
   127→
   128→    // Check if OPENROUTER_API_KEY is configured
   129→    const apiKey = process.env.OPENROUTER_API_KEY;
   130→    if (!apiKey) {
   131→      console.error('[API] OPENROUTER_API_KEY not configured');
   132→      return NextResponse.json(
   133→        {
   134→          success: false,
   135→          error: 'SERVICE_UNAVAILABLE',
   136→          message: 'Image generation service is not configured. Please contact support.',
   137→        },
   138→        { status: 503 }
   139→      );
   140→    }
   141→
   142→    // Parse request body
   143→    let body: ImageGenerationRequest;
   144→    try {
   145→      body = await request.json();
   146→    } catch (error) {
   147→      console.error('[API] Invalid JSON in request body:', error);
   148→      return NextResponse.json(
   149→        {
   150→          success: false,
   151→          error: 'INVALID_REQUEST',
   152→          message: 'Invalid request format',
   153→        },
   154→        { status: 400 }
   155→      );
   156→    }
   157→
   158→    // Validate request body
   159→    const { description, style } = body;
   160→
   161→    if (!description || typeof description !== 'string' || description.trim() === '') {
   162→      console.error('[API] Missing or invalid description');
   163→      return NextResponse.json(
   164→        {
   165→          success: false,
   166→          error: 'INVALID_DESCRIPTION',
   167→          message: 'Outfit description is required',
   168→        },
   169→        { status: 400 }
   170→      );
   171→    }
   172→
   173→    // Validate description length
   174→    if (description.length > 1000) {
   175→      console.error('[API] Description too long:', description.length);
   176→      return NextResponse.json(
   177→        {
   178→          success: false,
   179→          error: 'DESCRIPTION_TOO_LONG',
   180→          message: 'Outfit description is too long. Please keep it under 1000 characters.',
   181→        },
   182→        { status: 400 }
   183→      );
   184→    }
   185→
   186→    console.log('[API] Generating image for description:', {
   187→      descriptionLength: description.length,
   188→      style: style || 'default',
   189→    });
   190→
   191→    // Create image client and generate image
   192→    const imageClient = new OpenRouterImageClient(apiKey);
   193→
   194→    const result = await imageClient.generateOutfitImage(description, style);
   195→
   196→    const duration = Date.now() - startTime;
   197→    console.log('[API] Image generation completed in', duration, 'ms', {
   198→      success: result.success,
   199→      error: result.error || 'none',
   200→    });
   201→
   202→    // Return response with appropriate status code
   203→    if (result.success) {
   204→      return NextResponse.json(result, {
   205→        status: 200,
   206→        headers: {
   207→          'Cache-Control': 'no-cache, no-store, must-revalidate',
   208→        },
   209→      });
   210→    } else {
   211→      // Determine status code based on error type
   212→      let statusCode = 500;
   213→      if (result.error === 'RATE_LIMITED') {
   214→        statusCode = 429;
   215→      } else if (result.error === 'INVALID_DESCRIPTION') {
   216→        statusCode = 400;
   217→      } else if (result.error === 'SERVICE_UNAVAILABLE') {
   218→        statusCode = 503;
   219→      }
   220→
   221→      return NextResponse.json(result, {
   222→        status: statusCode,
   223→      });
   224→    }
   225→  } catch (error) {
   226→    const duration = Date.now() - startTime;
   227→    console.error('[API] Unexpected error during image generation:', error);
   228→    console.error('[API] Error occurred after', duration, 'ms');
   229→
   230→    return NextResponse.json(
   231→      {
   232→        success: false,
   233→        error: 'INTERNAL_ERROR',
   234→        message: 'An unexpected error occurred. Please try again later.',
   235→      },
   236→      { status: 500 }
   237→    );
   238→  }
   239→}
   240→
   241→/**
   242→ * GET handler - not supported
   243→ * Returns 405 Method Not Allowed
   244→ */
   245→export async function GET() {
   246→  return NextResponse.json(
   247→    {
   248→      success: false,
   249→      error: 'METHOD_NOT_ALLOWED',
   250→      message: 'GET method is not supported. Use POST to generate images.',
   251→    },
   252→    { status: 405 }
   253→  );
   254→}
   255→
   256→/**
   257→ * OPTIONS handler for CORS preflight
   258→ */
   259→export async function OPTIONS() {
   260→  return NextResponse.json(
   261→    {},
   262→    {
   263→      status: 200,
